import http from 'k6/http';
import { check, sleep } from 'k6';
import { Rate } from 'k6/metrics';

const cfg = {
  users: 2,
  iterations: 2,
  mode: 'flow'
};

const rows = [
  { username: 'bench-1', password: 'bench', quantity: 2 },
  { username: 'bench-2', password: 'bench', quantity: 3 },
  { username: 'bench-3', password: 'bench', quantity: 4 },
  { username: 'bench-4', password: 'bench', quantity: 5 },
  { username: 'bench-5', password: 'bench', quantity: 6 },
  { username: 'bench-6', password: 'bench', quantity: 7 },
  { username: 'bench-7', password: 'bench', quantity: 8 },
  { username: 'bench-8', password: 'bench', quantity: 9 },
  { username: 'bench-9', password: 'bench', quantity: 10 },
  { username: 'bench-10', password: 'bench', quantity: 11 },
  { username: 'bench-11', password: 'bench', quantity: 12 },
  { username: 'bench-12', password: 'bench', quantity: 13 },
  { username: 'bench-13', password: 'bench', quantity: 14 },
  { username: 'bench-14', password: 'bench', quantity: 15 },
  { username: 'bench-15', password: 'bench', quantity: 16 },
  { username: 'bench-16', password: 'bench', quantity: 17 }
];

const failure = new Rate('business_failure');

export const options = {
  scenarios: {
    journeys: {
      executor: 'per-vu-iterations',
      vus: cfg.users,
      iterations: cfg.iterations,
      maxDuration: '30s'
    }
  },
  thresholds: {
    checks: ['rate==1']
  }
};

const base = (__ENV.BASE_URL || 'http://127.0.0.1:8000').replace(/\/+$/, '');
let csrf = '';
let cart = '';
let grant = '';

function body(r) {
  try {
    return r.json();
  } catch (_) {
    return {};
  }
}

function headerValue(r, name) {
  const keys = Object.keys(r.headers || {});
  for (const key of keys) {
    if (key.toLowerCase() === name.toLowerCase()) {
      return r.headers[key];
    }
  }
  return undefined;
}

function toPath(location) {
  if (!location) {
    return '/';
  }
  if (location.indexOf('http://') === 0 || location.indexOf('https://') === 0) {
    const schemeEnd = location.indexOf('://');
    const pathStart = location.indexOf('/', schemeEnd + 3);
    if (pathStart === -1) {
      return '/';
    }
    return location.substring(pathStart);
  }
  return location;
}

function raw(path, method = 'GET', data = null, extra = {}) {
  const url = (path.indexOf('http://') === 0 || path.indexOf('https://') === 0)
    ? path
    : base + path;
  const headers = { 'Content-Type': 'application/json' };
  if (method !== 'GET' && csrf) {
    headers['X-CSRF-Token'] = csrf;
  }
  for (const key of Object.keys(extra || {})) {
    headers[key] = extra[key];
  }
  const r = http.request(method, url, data === null ? null : JSON.stringify(data), {
    headers,
    redirects: 0,
    timeout: '3s'
  });
  const b = body(r);
  if (b.csrf) {
    csrf = b.csrf;
  }
  if (path === '/v2/work') {
    failure.add(r.status >= 400 && !(r.status === 401 && b.error === 'expired') && r.status !== 429);
  }
  return r;
}

function login() {
  let r = raw('/v2/login-form');
  let token = r.html().find('input[name="csrf"][type="hidden"]').first().attr('value');
  if (!token) {
    token = r.html().find('input[name="csrf"]').first().attr('value');
  }
  if (!token) {
    check(false, { 'login csrf': () => false });
    return false;
  }
  csrf = token;
  const row = rows[(__VU - 1) % rows.length];
  r = raw('/v2/login', 'POST', {
    username: row.username,
    password: row.password,
    csrf: token
  });
  if (r.status === 302) {
    const location = headerValue(r, 'Location');
    if (!location) {
      check(false, { 'login redirect': () => false });
      return false;
    }
    r = raw(toPath(location));
  }
  const b = body(r);
  if (b.grant_id) {
    grant = b.grant_id;
  }
  check(r, { 'login': (resp) => resp.status === 200 });
  return r.status === 200;
}

function request(path, method = 'GET', data = null, extra = {}) {
  let r = raw(path, method, data, extra);
  if (r.status === 401) {
    const b = body(r);
    if (b.error === 'expired' || b.error === 'session') {
      const renewed = raw('/v2/session/renew', 'POST', {});
      if (renewed.status !== 200) {
        const loggedIn = login();
        if (!loggedIn) {
          return r;
        }
      }
      if (cart) {
        raw('/v2/carts/' + cart + '/recover', 'POST', {});
      }
      r = raw(path, method, data, extra);
    }
  }
  return r;
}

function flow() {
  csrf = '';
  cart = '';
  grant = '';

  if (!login()) {
    return;
  }

  let page = '/v2/catalog';
  let product = null;

  for (let n = 0; n < 3 && page; n++) {
    const b = body(request(page));
    const products = b.data && Array.isArray(b.data.products) ? b.data.products : [];
    product = products.find((p) => Array.isArray(p.variants) && p.variants.some((v) => v.in_stock));
    if (product) {
      break;
    }
    page = b.next;
  }

  if (!product) {
    check(false, { 'eligible product': () => false });
    return;
  }

  const variant = product.variants.find((v) => v.in_stock);
  const cartPayload = {
    product_id: product.id,
    variant_id: variant.id
  };

  if (grant) {
    cartPayload.grant_id = grant;
  }

  let r = request('/v2/carts', 'POST', cartPayload);
  cart = body(r).id;
  const etag = headerValue(r, 'Etag');
  check(r, { 'cart': (resp) => resp.status === 201 });

  if (!cart) {
    check(false, { 'cart id': () => false });
    return;
  }

  const orderHeaders = { 'Idempotency-Key': cart };
  if (etag) {
    orderHeaders['If-Match'] = etag;
  }

  r = request('/v2/orders', 'POST', { cart_id: cart }, orderHeaders);
  check(r, { 'accepted': (resp) => resp.status === 201 && body(resp).accepted === true });
}

function work(override) {
  if (!csrf) {
    if (!login()) {
      return;
    }
  }
  const path = override || '/v2/work';
  let r = request(path, 'POST', {});
  for (let n = 0; n < 4 && r.status === 429; n++) {
    const retryAfter = headerValue(r, 'Retry-After');
    sleep(Number(retryAfter || '1') + 0.01);
    r = request(path, 'POST', {});
  }
  check(r, {
    'operation or expected throttle': (resp) =>
      (resp.status === 200 && body(resp).ok === true)
  });
}

export default function () {
  flow();
}

export function browse() {
  work('/v2/browse');
}

export function checkout() {
  flow();
}

