import {check, sleep} from 'k6';
import {Rate} from 'k6/metrics';

const cfg = {"users": 2, "iterations": 2, "mode": "flow"};
const rows = [
  {"username": "bench-1", "password": "bench", "quantity": 2},
  {"username": "bench-2", "password": "bench", "quantity": 3},
  {"username": "bench-3", "password": "bench", "quantity": 4},
  {"username": "bench-4", "password": "bench", "quantity": 5},
  {"username": "bench-5", "password": "bench", "quantity": 6},
  {"username": "bench-6", "password": "bench", "quantity": 7},
  {"username": "bench-7", "password": "bench", "quantity": 8},
  {"username": "bench-8", "password": "bench", "quantity": 9},
  {"username": "bench-9", "password": "bench", "quantity": 10},
  {"username": "bench-10", "password": "bench", "quantity": 11},
  {"username": "bench-11", "password": "bench", "quantity": 12},
  {"username": "bench-12", "password": "bench", "quantity": 13},
  {"username": "bench-13", "password": "bench", "quantity": 14},
  {"username": "bench-14", "password": "bench", "quantity": 15},
  {"username": "bench-15", "password": "bench", "quantity": 16},
  {"username": "bench-16", "password": "bench", "quantity": 17}
];
const failure = new Rate('business_failure');

export const options = {
  "scenarios": {
    "journeys": {
      "executor": "per-vu-iterations",
      "vus": 2,
      "iterations": 2,
      "maxDuration": "30s"
    }
  },
  "thresholds": {
    "checks": ["rate==1"]
  }
};

const base = __ENV.BASE_URL || 'http://127.0.0.1:8000';
let csrf = '';
let cart = '';
let grant = '';

function body(r) {
  try { return r.json(); } catch (_) { return {}; }
}

function getHeader(r, name) {
  if (!r || !r.headers) return null;
  if (r.headers[name] !== undefined) return r.headers[name];
  const lower = name.toLowerCase();
  for (const key of Object.keys(r.headers)) {
    if (key.toLowerCase() === lower) return r.headers[key];
  }
  return null;
}

function formInputValue(r, name) {
  let val = '';
  try {
    const doc = r.html();
    const el = doc.find('input[name="' + name + '"]').first();
    if (el && el.attr) val = el.attr('value') || '';
  } catch (_) {}

  if (!val) {
    const text = r.body || '';
    const q = name.replace(/[.*+?^${}()|[\]\\]/g, '\\$&');
    const patterns = [
      new RegExp('name=["\']' + q + '["\'][^>]*value=["\']([^"\']+)["\']', 'i'),
      new RegExp('value=["\']([^"\']+)["\'][^>]*name=["\']' + q + '["\']', 'i'),
      new RegExp('name=' + q + '\\s+value=["\']([^"\']+)["\']', 'i')
    ];
    for (const p of patterns) {
      const m = text.match(p);
      if (m) return m[1];
    }
  }

  return val;
}

function resolveUrl(path) {
  if (path.indexOf('http') === 0) return path;
  const cleanBase = base.replace(/\/+$/, '');
  return cleanBase + (path.indexOf('/') === 0 ? path : '/' + path);
}

function raw(path, method = 'GET', data = null, extra = {}) {
  const headers = {'Content-Type': 'application/json'};
  if (csrf) headers['X-CSRF-Token'] = csrf;
  Object.assign(headers, extra);

  const r = http.request(method, resolveUrl(path), data === null ? null : JSON.stringify(data), {
    headers: headers,
    redirects: 0,
    timeout: '3s'
  });

  const b = body(r);
  if (b && b.csrf) csrf = b.csrf;

  if (path === '/v2/work') {
    const expectedExpiry = r.status === 401 && b && b.error === 'expired';
    failure.add(r.status >= 400 && !expectedExpiry && r.status !== 429);
  }

  return r;
}

function login() {
  csrf = '';
  let r = raw('/v2/login-form');
  const token = formInputValue(r, 'csrf');
  if (!token) {
    check(false, {'login form csrf': x => x});
    return false;
  }

  const row = rows[(__VU - 1) % rows.length];
  csrf = token;

  r = raw('/v2/login', 'POST', {
    username: row.username,
    password: row.password,
    csrf: token
