    }

    if (cart) {
      raw('/v2/carts/' + cart + '/recover', 'POST', {});
    }

    r = raw(path, method, data, extra);
  }

  return r;
}

function work(override) {
  if (cfg.workload || !csrf) login();

  const path = override || cfg.path || '/v2/work';
  let r = request(path, 'POST', {});

  for (let n = 0; n < 4 && r.status === 429; n++) {
    const retryAfter = getHeader(r, 'Retry-After');
    sleep(Number(retryAfter) + 0.01);
    r = request(path, 'POST', {});
  }

  check(r, {
    'operation or expected throttle': x =>
      (x.status === 200 && body(x).ok === true) ||
      (cfg.completion && x.status === 429)
  });
}

function flow() {
  csrf = '';
  cart = '';
  grant = '';

  if (!login()) return;

  if (cfg.mode === 'challenge') {
    let r = request('/v2/challenge-form');
    const form = r.html().find('form');
    const token = form.find('input[name="challenge"]').first().attr('value');
    const action = form.attr('action');

    r = request(action, 'POST', {challenge: token});
    const loc = getHeader(r, 'Location');
    if (!loc) return;

    r = request(loc);
    const b = body(r);
    if (b.grant_id) grant = b.grant_id;
  }

  let page = cfg.mode === 'pagination' ? '/v2/catalog/page' : '/v2/catalog';
  let product = null;

  for (let n = 0; n < 3 && page; n++) {
    const b = body(request(page));
    const data = b && b.data;

    if (data) {
      const products = data.products;
      if (products && products.find) {
        product = products.find(p => p.variants && p.variants.some(v => v.in_stock));
      } else if (data.product && data.product.variants) {
        product = data.product;
      } else if (data.id && data.variants) {
        product = data;
      }
    }

    if (product) break;
    page = data && data.next ? data.next : null;
  }

  if (!product) {
    check(false, {'eligible product': x => x});
    return;
  }

  const variant = product.variants.find(v => v.in_stock);
  const payload = {product_id: product.id, variant_id: variant.id};
  if (grant) payload.grant_id = grant;

  let r = request('/v2/carts', 'POST', payload);
  const created = body(r);
  cart = created.id || '';
  let etag = getHeader(r, 'Etag') || getHeader(r, 'ETag');

  check(r, {'cart': x => x.status === 201 && !!cart});
  if (!cart) return;

  if (cfg.mode === 'etag' || cfg.mode === 'data') {
    const quantity = cfg.mode === 'data'
      ? rows[(__VU - 1) % rows.length].quantity
      : (cfg.quantity || 2);

    let headers = {};
    if (etag) headers['If-Match'] = etag;

    r = request('/v2/carts/' + cart, 'PATCH', {quantity: quantity}, headers);

    if (r.status === 412) {
      const reread = request('/v2/carts/' + cart);
      etag = getHeader(reread, 'Etag') || getHeader(reread, 'ETag');
      headers = {};
      if (etag) headers['If-Match'] = etag;
      r = request('/v2/carts/' + cart, 'PATCH', {quantity: quantity}, headers);
    }

    etag = getHeader(r, 'Etag') || getHeader(r, 'ETag');
    check(r, {'update': x => x.status === 200});
  }

  let reservation;
  if (cfg.mode === 'reservation') {
    r = request('/v2/reservations', 'POST', {cart_id: cart});
    const statusUrl = body(r).status_url;

    for (let n = 0; n < 5; n++) {
      sleep(0.05);
      r = request(statusUrl);
      const b = body(r);

      if (b.status === 'ready') {
        reservation = b.reservation_id;
        break;
      }

      if (b.status === 'failed') {
        check(false, {'reservation ready': x => x});
        return;
      }
    }

    if (!reservation) return;
  }

  const orderPayload = {cart_id: cart};
  if (reservation) orderPayload.reservation_id = reservation;

  const orderHeaders = {'Idempotency-Key': cart};
  if (etag) orderHeaders['If-Match'] = etag;

  r = request('/v2/orders', 'POST', orderPayload, orderHeaders);
  check(r, {'accepted': x => x.status === 201 && body(x).accepted === true});

  if (cfg.mode === 'threshold') raw('/v2/health');
}

export default function() {
  if (cfg.workload) {
    if (cfg.operation === 'journey') flow();
    else work();
  } else if (cfg.mode === 'errors') {
    login();
    for (let n = 0; n < 4; n++) work();
  } else {
    flow();
  }
}

export function browse() {
  work('/v2/browse');
}

export function checkout() {
  flow();
}

