const base = (__ENV.BASE_URL || 'http://127.0.0.1:8000').replace(/\/+$/, '');
const cfg = {
  mode: __ENV.MODE || 'denial',
  workload: __ENV.WORKLOAD === 'true',
  operation: __ENV.OPERATION || 'journey',
  path: __ENV.PATH || '/v2/work',
  quantity: Number(__ENV.QUANTITY || 2),
};

function body(r) {
  try { return r.json(); } catch (_) { return {}; }
}

function getHeader(r, name) {
  const headers = r.headers || {};
  for (const key in headers) {
    if (key.toLowerCase() === name.toLowerCase()) return headers[key];
  }
  return '';
}

function resolveUrl(path) {
  if (!path) return base;
  if (/^https?:\/\//i.test(path)) return path;
  return path.startsWith('/') ? base + path : base + '/' + path;
}

function getAttr(tag, name) {
  const attrRe = /([a-zA-Z_][a-zA-Z0-9_-]*)\s*=\s*(?:"([^"]*)"|'([^']*)'|([^\s>]+))/g;
  let match;
  while ((match = attrRe.exec(tag)) !== null) {
    if (match[1].toLowerCase() === name.toLowerCase()) {
      return match[2] || match[3] || match[4] || '';
    }
  }
  return '';
}

function findInputValueByName(html, name) {
  const inputRe = /<input\b[^>]*>/gi;
  let match;
  while ((match = inputRe.exec(html)) !== null) {
    const tag = match[0];
    if (getAttr(tag, 'name') !== name) continue;
    const value = getAttr(tag, 'value');
    if (value !== '') return value;
  }
  return '';
}

function findFormAction(html, pathPart) {
  const formRe = /<form\b[^>]*>/gi;
  let match;
  while ((match = formRe.exec(html)) !== null) {
    const action = getAttr(match[0], 'action');
    if (action && action.indexOf(pathPart) !== -1) return action;
  }
  return '';
}

function raw(path, method = 'GET', data = null, extra = {}) {
  const headers = {};
  if (data !== null) headers['Content-Type'] = 'application/json';
  if (csrf) headers['X-CSRF-Token'] = csrf;
  for (const key in extra) {
    if (extra[key] !== undefined && extra[key] !== null) headers[key] = extra[key];
  }

  const r = http.request(method, resolveUrl(path), data === null ? null : JSON.stringify(data), {
    headers: headers,
    redirects: 0,
    timeout: '5s',
  });

  const parsedBody = body(r);
  if (parsedBody.csrf) csrf = parsedBody.csrf;

  if (path === '/v2/work') {
    const expectedExpiry = r.status === 401 && parsedBody.error === 'expired';
    const scheduled429 = r.status === 429;
    failure.add(r.status >= 400 && !expectedExpiry && !scheduled429);
  }

  return r;
}

function login() {
  csrf = '';
  let r = raw('/v2/login-form');
  const token = findInputValueByName(r.body, 'csrf');

  const row = rows[(__VU - 1) % rows.length];
  r = raw('/v2/login', 'POST', { username: row.username, password: row.password, csrf: token });

  if (r.status === 302) {
    const location = getHeader(r, 'Location');
    if (location) {
      r = raw(location);
      const parsedBody = body(r);
      if (parsedBody.grant_id) grant = parsedBody.grant_id;
    }
  }

  check(r, { login: (r) => r.status === 200 });
}

