  const renew = raw('/v2/session/renew', 'POST', {});
  if (renew.status !== 200) {
    grant = '';
    csrf = '';
    login();
  }
}

function request(path, method = 'GET', data = null, extra = {}) {
  let r = raw(path, method, data, extra);

  if (r.status === 401) {
    const parsedBody = body(r);
    if (parsedBody.error === 'expired' || parsedBody.error === 'session') {
      recoverSession();
      if (cart) {
        raw('/v2/carts/' + cart + '/recover', 'POST', {});
