  if (!csrf) login();
  const path = override || '/v2/work';
  let r = request(path, 'POST', {});

  for (let n = 0; n < 4 && r.status === 429; n++) {
    const retryAfter = Number(getHeader(r, 'Retry-After') || 1);
    sleep(retryAfter + 0.01);
    r = request(path, 'POST', {});
  }

  check(r, { work: (r) => (r.status === 200 && body(r).ok === true) || r.status === 429 });
}

