  csrf = '';
  cart = '';
  grant = '';
  login();

  if (cfg.mode === 'challenge') {
    let r = request('/v2/challenge-form');
    const action = findFormAction(r.body, '/v2/challenges/');
    const challenge = findInputValueByName(r.body, 'challenge');

    if (!action || !challenge) {
      check(false, { 'challenge form': (x) => false });
      return;
    }

    r = request(action, 'POST', { challenge: challenge });
    if (r.status === 302) {
      const location = getHeader(r, 'Location');
      if (location) {
        r = raw(location);
        const parsedBody = body(r);
        if (parsedBody.grant_id) grant = parsedBody.grant_id;
      }
    }
  }

  let page = cfg.mode === 'pagination' ? '/v2/catalog/page' : '/v2/catalog';
  let product = null;

  for (let n = 0; n < 3 && page; n++) {
    const r = request(page);
    const parsedBody = body(r);
    const products = (parsedBody.data && parsedBody.data.products) || [];
    product = products.find((p) => p.variants && p.variants.some((v) => v.in_stock));
    if (product) break;
    page = parsedBody.next || null;
  }

  if (!product) {
    check(false, { 'eligible product': (x) => false });
    return;
