  let etag = getHeader(r, 'ETag');

  check(r, { cart: (r) => r.status === 201 && cart !== '' });
  if (!cart) return;

  if (cfg.mode === 'etag' || cfg.mode === 'data') {
    const quantity = cfg.mode === 'data' ? rows[(__VU - 1) % rows.length].quantity : cfg.quantity;
    const headers = { 'If-Match': etag };
    r = request('/v2/carts/' + cart, 'PATCH', { quantity: quantity }, headers);

    if (r.status === 412) {
      const read = request('/v2/carts/' + cart);
      etag = getHeader(read, 'ETag') || etag;
      r = request('/v2/carts/' + cart, 'PATCH', { quantity: quantity }, { 'If-Match': etag });
    }

    etag = getHeader(r, 'ETag') || etag;
    check(r, { update: (r) => r.status === 200 });
  }

  let reservation_id;
  if (cfg.mode === 'reservation') {
    r = request('/v2/reservations', 'POST', { cart_id: cart });
    const statusUrl = body(r).status_url;

    for (let n = 0; n < 5; n++) {
      sleep(0.05);
      r = request(statusUrl);
      const parsedBody = body(r);

      if (parsedBody.status === 'ready') {
        reservation_id = parsedBody.reservation_id;
        break;
      }

      if (parsedBody.status === 'failed') {
        check(false, { 'reservation ready': (x) => false });
        return;
      }
    }

    if (!reservation_id) {
      check(false, { 'reservation ready': (x) => false });
      return;
    }
  }

