const businessFailure = new Rate('business_failure');

export const options = {
  scenarios: {
    journeys: {
      executor: 'per-vu-iterations',
      vus: EXECUTION.users,
      iterations: EXECUTION.iterations,
      maxDuration: '30s',
    },
  },
};

const BASE = (__ENV.BASE_URL || 'http://127.0.0.1:8000').replace(/\/$/, '');

let csrf = '';
let cart = '';
let grant = '';
let currentRow = null;

function url(path) {
  if (!path) return BASE;
  if (path.startsWith('http://') || path.startsWith('https://')) return path;
  return BASE + path;
}

function body(r) {
  try { return r.json(); } catch (_) { return {}; }
}

function firstValue(html, selector) {
  if (!html) return '';
  const inputs = html.find(selector).toArray();
  for (const input of inputs) {
    const value = input.attr('value');
    if (value && value.trim()) return value.trim();
  }
  return '';
}

function accountFromCsv(path) {
  const text = open(path);
  const lines = text.split(/\r?\n/).filter((line) => line.trim());
  if (lines.length < 2) throw new Error(`${path} has no account row`);
  const fields = lines[1].split(',').map((s) => s.trim());
  return {
    username: fields[0],
    password: fields[1],
    quantity: parseInt(fields[2], 10),
    delay: parseInt(fields[3], 10),
  };
}

function loadAccounts() {
  let rows;
  try {
    rows = JSON.parse(open('/fixtures/accounts.json'));
  } catch (_) {
    rows = [
      accountFromCsv('/fixtures/account-1.csv'),
      accountFromCsv('/fixtures/account-2.csv'),
    ];
  }
  if (!Array.isArray(rows) || rows.length < EXECUTION.users) {
    rows = [
      accountFromCsv('/fixtures/account-1.csv'),
      accountFromCsv('/fixtures/account-2.csv'),
    ];
  }
  return rows;
}

export function setup() {
  const rows = loadAccounts().slice(0, EXECUTION.users);
  const usernames = rows.map((r) => r.username);
  if (new Set(usernames).size !== EXECUTION.users) {
    throw new Error('accounts must be distinct for exclusive sessions');
  }
  return { accounts: rows };
