import http from 'k6/http';
import { parseHTML } from 'k6/html';
import { sleep } from 'k6';

const BASE_URL = __ENV.BASE_URL || 'http://127.0.0.1:8000';
const VU_ID = __VU;
const NUM_WORK_VUS = 2;
const PHASE1_END_MS = 15000;
const PHASE2_END_MS = 25000;
const PHASE3_END_MS = 35000;
const MAX_429_RETRIES = 4;

function extractCsrf(body) {
  try {
    const doc = parseHTML(body);
    const input = doc.find('input[name="csrf"]').first();
    if (input) {
      const val = input.attr('value');
      if (val) return val;
    }
  } catch (e) {}

  const tag = body.match(/<input[^>]*name=["']csrf["'][^>]*>/i);
  if (tag) {
    const val = tag[0].match(/value=["']([^"']+)["']/i);
    if (val) return val[1];
    const val2 = tag[0].match(/value=([^ >]+)/i);
    if (val2) return val2[1].replace(/["']/g, '');
  }

  throw new Error('Could not extract CSRF token');
}

function getLoginFormCsrf() {
  const res = http.get(`${BASE_URL}/v2/login-form`, { redirects: 0 });
  if (res.status !== 200) {
    throw new Error(`Login form status ${res.status}`);
  }
  return extractCsrf(res.body);
}

function login(username, password) {
  const csrf = getLoginFormCsrf();

  let res = http.post(
    `${BASE_URL}/v2/login`,
    JSON.stringify({ username, password, csrf }),
    {
      headers: { 'Content-Type': 'application/json' },
      redirects: 0,
    }
  );

  if (res.status === 302) {
    const loc = res.headers['location'] || res.headers['Location'];
    if (!loc) {
      throw new Error('No Location after login 302');
    }
    const url = loc.startsWith('http') ? loc : `${BASE_URL}${loc}`;
    res = http.get(url, { redirects: 0 });
  }

  if (res.status !== 200) {
    throw new Error(`Login status ${res.status}`);
  }

  let body;
  try {
    body = JSON.parse(res.body);
  } catch (e) {
    throw new Error('Invalid login JSON');
  }

  if (!body.csrf) {
    throw new Error('No csrf in login response');
  }

  return body.csrf;
}

function renewSession(csrf) {
  const res = http.post(
    `${BASE_URL}/v2/session/renew`,
    '{}',
    {
      headers: {
        'Content-Type': 'application/json',
        'X-CSRF-Token': csrf,
      },
      redirects: 0,
    }
  );

  if (res.status === 200) {
    let body;
    try {
      body = JSON.parse(res.body);
    } catch (e) {}

    if (body && body.csrf) {
      return body.csrf;
    }
  }

  throw new Error('Session renew failed');
}

function freshLogin(username, password) {
  return login(username, password);
}

function postWork(csrf, username, password) {
  let currentCsrf = csrf;
  let retry429 = 0;
  let operationRetried = false;

  while (true) {
    const res = http.post(
      `${BASE_URL}/v2/work`,
      '{}',
      {
        headers: {
          'Content-Type': 'application/json',
          'X-CSRF-Token': currentCsrf,
        },
        redirects: 0,
      }
    );

    if (res.status === 200) {
      let body;
      try {
        body = JSON.parse(res.body);
      } catch (e) {
        throw new Error('Invalid work JSON');
      }

      if (body && body.ok === true) {
        if (body.csrf) {
          currentCsrf = body.csrf;
        }
        return { ok: true, csrf: currentCsrf };
      }

      throw new Error('Work response ok not true');
    }

    if (res.status === 429) {
      retry429++;
      if (retry429 > MAX_429_RETRIES) {
        return { ok: false, csrf: currentCsrf };
      }

      const ra = res.headers['retry-after'] || res.headers['Retry-After'];
      const waitS = ra ? parseFloat(ra) : 1;
      sleep(waitS);
      continue;
    }

    if (res.status === 401) {
      if (operationRetried) {
        throw new Error('401 retry failed');
      }
      operationRetried = true;

      let error = null;
      try {
        const body = JSON.parse(res.body);
        error = body.error;
      } catch (e) {}

      if (error === 'denied') {
        throw new Error('401 denied');
      }

      try {
        currentCsrf = renewSession(currentCsrf);
      } catch (e) {
        currentCsrf = freshLogin(username, password);
      }

      continue;
    }

    throw new Error(`Unexpected work status ${res.status}`);
  }
}

function generateSendTimes(t0) {
  const phases = [
    { start: t0, end: t0 + PHASE1_END_MS, rate: 5 },
    { start: t0 + PHASE1_END_MS, end: t0 + PHASE2_END_MS, rate: 15 },
    { start: t0 + PHASE2_END_MS, end: t0 + PHASE3_END_MS, rate: 5 },
  ];

  const times = [];

  for (const phase of phases) {
    const period = NUM_WORK_VUS * 1000 / phase.rate;
    const offset = (VU_ID - 1) * 1000 / phase.rate;

    for (let t = phase.start + offset; t < phase.end; t += period) {
      times.push(t);
    }
  }

  return times.sort((a, b) => a - b);
}

export function setup() {
  return { t0: Date.now() + 7000 };
}

export default function (data) {
  const username = VU_ID <= 16 ? `bench-${VU_ID}` : 'bench';
  let csrf = login(username, 'bench');

  const t0 = data.t0;
  const wait = t0 - Date.now();
  if (wait > 0) {
    sleep(wait / 1000);
  }

  const sendTimes = generateSendTimes(t0);

  for (const sendTime of sendTimes) {
    const delay = sendTime - Date.now();
    if (delay > 0) {
      sleep(delay / 1000);
    }

    try {
      const result = postWork(csrf, username, 'bench');
      if (result.ok && result.csrf) {
        csrf = result.csrf;
      }
    } catch (e) {
      // Continue after unexpected error; the scoring is based on successful work events.
    }
  }
}
