import http from 'k6/http';
import { sleep } from 'k6';

const BASE = (__ENV.BASE_URL || 'http://127.0.0.1:8000').replace(/\/$/, '');
const USERS = [
  'bench-1', 'bench-2', 'bench-3', 'bench-4',
  'bench-5', 'bench-6', 'bench-7', 'bench-8',
  'bench-9', 'bench-10', 'bench-11', 'bench-12',
  'bench-13', 'bench-14', 'bench-15', 'bench-16',
  'bench'
];

export const options = {
  discardResponseBodies: false,
  redirects: 0,
  scenarios: {
    work: {
      executor: 'ramping-arrival-rate',
      timeUnit: '1s',
      startRate: 5,
      preAllocatedVUs: 17,
      maxVUs: 17,
      stages: [
        { duration: '5s', target: 5 },
        { duration: '10s', target: 5 },
        { duration: '10s', target: 15 },
        { duration: '10s', target: 5 },
        { duration: '5s', target: 0 },
      ],
    },
  },
};

function parseJson(body) {
  if (!body) return null;
  try {
    return JSON.parse(body);
  } catch (e) {
    return null;
  }
}

function parseCsrf(body) {
  if (!body) return null;

  const json = parseJson(body);
  if (json && typeof json === 'object' && 'csrf' in json) {
    return json.csrf;
  }

  const patterns = [
    /<input[^>]+name\s*=\s*["']csrf["'][^>]+value\s*=\s*["']([^"']+)["']/i,
    /<input[^>]+value\s*=\s*["']([^"']+)["'][^>]+name\s*=\s*["']csrf["']/i,
    /<input[^>]*name\s*=\s*["']csrf["'][^>]*value\s*=\s*["']([^"']+)["']/i,
    /<input[^>]*value\s*=\s*["']([^"']+)["'][^>]*name\s*=\s*["']csrf["']/i,
    /<input[^>]+name\s*=\s*["']csrf["'][^>]+value\s*=\s*([^\s>]+)/i,
    /<input[^>]+value\s*=\s*([^\s>]+)[^>]+name\s*=\s*["']csrf["']/i,
  ];

  for (const pattern of patterns) {
    const match = body.match(pattern);
    if (match) return match[1];
  }

  return null;
}

function joinUrl(base, loc) {
  if (/^https?:\/\//i.test(loc)) return loc;
  if (loc.startsWith('/')) return base + loc;
  return `${base}/${loc}`;
}

function parseRetryAfter(value) {
  if (!value) return 1;
  const trimmed = value.trim();
  if (/^\d+(\.\d+)?$/.test(trimmed)) {
    const seconds = parseFloat(trimmed);
    if (!isNaN(seconds) && seconds >= 0) return seconds;
  }
  const date = new Date(trimmed).getTime();
  if (!isNaN(date)) {
    return Math.max(0, (date - Date.now()) / 1000);
  }
  return 1;
}

function currentUser() {
  return USERS[(__VU - 1) % USERS.length];
}

function login(user) {
  const formRes = http.get(`${BASE}/v2/login-form`, { redirects: 0 });
  if (formRes.status !== 200) {
    throw new Error(`login_form status ${formRes.status}`);
  }

  const csrf = parseCsrf(formRes.body);
  if (!csrf) {
    throw new Error('login_form missing csrf');
  }

  const loginRes = http.post(`${BASE}/v2/login`, JSON.stringify({
    username: user,
    password: 'bench',
    csrf,
  }), {
    headers: { 'Content-Type': 'application/json' },
    redirects: 0,
  });

  if (loginRes.status === 302) {
    const loc = loginRes.headers['Location'] || loginRes.headers['location'];
    if (!loc) throw new Error('login 302 missing Location');

    const followUrl = joinUrl(BASE, loc);
    const followRes = http.get(followUrl, { redirects: 0 });

    if (followRes.status < 200 || followRes.status >= 300) {
      throw new Error(`login follow status ${followRes.status}`);
    }

    const followCsrf = parseCsrf(followRes.body);
    return followCsrf || csrf;
  }

  if (loginRes.status === 200 || loginRes.status === 201 || loginRes.status === 204) {
    const json = parseJson(loginRes.body);
    if (json && json.csrf) return json.csrf;
    return csrf;
  }

  throw new Error(`login status ${loginRes.status}`);
}

function doWork(initialToken) {
  let token = initialToken;
  let retries429 = 0;
  let expiredRetried = false;
  let sessionRetried = false;

  while (true) {
    const res = http.post(`${BASE}/v2/work`, '{}', {
      headers: {
        'Content-Type': 'application/json',
        'X-CSRF-Token': token,
      },
    });

    const json = parseJson(res.body);
    if (json && json.csrf) token = json.csrf;

    if (res.status === 200) {
      if (json && json.ok === true) return;
      throw new Error(`work 200 ok!=true: ${res.body}`);
    }

    if (res.status === 429) {
      retries429 += 1;
      if (retries429 >= 4) throw new Error('work 429 retry limit exhausted');

      const retryAfter = parseRetryAfter(res.headers['Retry-After'] || res.headers['retry-after']);
      sleep(retryAfter);
      continue;
    }

    if (res.status === 401) {
      const error = json && json.error;

      if (error === 'expired') {
        if (expiredRetried) throw new Error('work 401 expired after renewal');
        expiredRetried = true;

        const renewRes = http.post(`${BASE}/v2/session/renew`, '{}', {
          headers: {
            'Content-Type': 'application/json',
            'X-CSRF-Token': token,
          },
        });

        if (renewRes.status < 200 || renewRes.status >= 300) {
          if (sessionRetried) throw new Error('renew failed and session retry exhausted');
          sessionRetried = true;
          token = login(currentUser());
          continue;
        }

        const renewJson = parseJson(renewRes.body);
        if (renewJson && renewJson.csrf) token = renewJson.csrf;
        continue;
      }

      if (error === 'session') {
        if (sessionRetried) throw new Error('work 401 session retry exhausted');
        sessionRetried = true;
        token = login(currentUser());
        continue;
      }

      if (error === 'denied') {
        throw new Error('work 401 denied');
      }

      throw new Error(`work 401 unexpected: ${res.body}`);
    }

    if (res.status >= 500) {
      throw new Error(`work status ${res.status} unexpected`);
    }

    throw new Error(`work status ${res.status} unexpected`);
  }
}

export default function () {
  const token = login(currentUser());
  doWork(token);
