  pushRate(ANCHOR_MS, WARMUP_MS, 5);
  pushRate(SCORE_START, PLATEAU_MS, 5);
  pushRate(SCORE_START + PLATEAU_MS, PLATEAU_MS, 15);
  pushRate(SCORE_START + 2 * PLATEAU_MS, PLATEAU_MS, 5);

  return times;
}

const SCHEDULE = generateSchedule();

function resolveUrl(location) {
  if (location && (location.startsWith('http://') || location.startsWith('https://'))) {
    return location;
  }
  return BASE_URL + (location ? (location.startsWith('/') ? location : '/' + location) : '');
}

function extractCsrfFromHtml(html) {
  const pattern = /<input\b([^>]*?)\/?>/gi;
  let match;
  while ((match = pattern.exec(html)) !== null) {
    const attrs = match[1];
    if (/(?:^|\s)name\s*=\s*(?:"csrf"|'csrf'|csrf)(?=\s|>|$)/i.test(attrs)) {
      const valueMatch = attrs.match(/value\s*=\s*["']?([^"'\s>]*)/i);
      if (valueMatch) return valueMatch[1];
    }
  }
  throw new Error('CSRF input not found in login form');
}

function getLoginFormCsrf() {
  const res = http.get(`${BASE_URL}/v2/login-form`);
  if (res.status !== 200) {
    throw new Error(`login form unexpected status ${res.status}`);
  }
  return extractCsrfFromHtml(res.body);
}

function login(username) {
  let csrf = getLoginFormCsrf();
  let res = http.post(
    `${BASE_URL}/v2/login`,
    JSON.stringify({
      username: username,
      password: PASSWORD,
      csrf: csrf,
    }),
    {
      headers: {
        'Content-Type': 'application/json',
        'X-CSRF-Token': csrf,
      },
    }
  );

  if (res.status === 302) {
    const location = res.headers['Location'] || res.headers['location'];
    if (!location) {
      throw new Error('login 302 without Location');
    }
    res = http.get(resolveUrl(location));
  }

  if (res.status >= 400) {
    throw new Error(`login failed with status ${res.status}`);
  }

  try {
    const body = JSON.parse(res.body);
    if (body.csrf) {
      csrf = body.csrf;
    }
  } catch (e) {
    try {
      const found = extractCsrfFromHtml(res.body);
      if (found) {
        csrf = found;
      }
    } catch (e2) {
      // keep previous csrf
    }
  }

  return csrf;
}

function renewSession(csrf) {
  const res = http.post(
    `${BASE_URL}/v2/session/renew`,
    JSON.stringify({}),
    {
      headers: {
        'Content-Type': 'application/json',
        'X-CSRF-Token': csrf,
      },
    }
  );

  if (res.status >= 400) {
    return null;
  }

  try {
    const body = JSON.parse(res.body);
    if (body.csrf) {
      return body.csrf;
    }
  } catch (e) {
    // ignore
  }

  return null;
}

function classify401(res) {
  try {
    const body = JSON.parse(res.body);
    return body.error || null;
  } catch (e) {
    return null;
  }
}

function performWork(csrf, username) {
  let currentCsrf = csrf;
  let retry429 = 0;
  let retried401 = false;

  while (true) {
    const start = Date.now();
    let res;

    try {
      res = http.post(
        `${BASE_URL}/v2/work`,
        JSON.stringify({}),
        {
          headers: {
            'Content-Type': 'application/json',
            'X-CSRF-Token': currentCsrf,
          },
        }
      );
    } catch (e) {
      throw new Error(`work HTTP error: ${e.message}`);
    }

    if (res.status === 429) {
      retry429++;
      if (retry429 > 4) {
        throw new Error('work scheduled 429 retries exhausted');
      }
      const retryAfter = parseInt(retryAfterHeader(res), 10) || 1;
      sleep(retryAfter);
      continue;
    }

    if (res.status === 401) {
      const err = classify401(res);
      if (err === 'denied') {
        throw new Error('work 401 denied');
      }
      if (retried401) {
        throw new Error('work 401 retry failed');
      }
      retried401 = true;

      if (err === 'expired') {
        const renewed = renewSession(currentCsrf);
        if (renewed) {
          currentCsrf = renewed;
        } else {
          currentCsrf = login(username);
        }
      } else if (err === 'session') {
        currentCsrf = login(username);
      } else {
        throw new Error(`unexpected work 401 error=${err}`);
      }

      continue;
    }

    if (res.status >= 400) {
      throw new Error(`unexpected work status ${res.status}`);
    }

    let ok = false;
    try {
      const body = JSON.parse(res.body);
      if (body.ok === true) {
        ok = true;
      }
      if (body.csrf) {
        currentCsrf = body.csrf;
      }
    } catch (e) {
      // not JSON
    }

    if (!ok) {
      throw new Error('work response missing ok=true');
    }

    return { csrf: currentCsrf, start: start };
  }
}

function retryAfterHeader(res) {
  return res.headers['Retry-After'] || res.headers['retry-after'] || '1';
}

export default function () {
  const vuId = execution.vu.idInTest;
  const username = `bench-${vuId}`;
  let csrf = login(username);

  let pointer = 0;
  while (true) {
    const index = pointer * 2 + (vuId - 1);
    if (index >= SCHEDULE.length) {
      break;
    }

    const scheduleTime = SCHEDULE[index];
    const now = Date.now();
    if (now > DRAIN_END) {
      break;
    }

    if (now < scheduleTime) {
      sleep((scheduleTime - now) / 1000);
    }

    if (Date.now() > DRAIN_END) {
      break;
    }

    const result = performWork(csrf, username);
    csrf = result.csrf;
    pointer++;
  }
}
